// 見本: 音を粗くする（ビットクラッシャー）。bits の値で粗さが変わる
class SampleCrusher extends AudioWorkletProcessor {
  static get parameterDescriptors() { return [{ name: "bits", defaultValue: 6, minValue: 1, maxValue: 16 }]; }
  process(inputs, outputs, parameters) {
    const input = inputs[0], output = outputs[0];
    const step = Math.pow(0.5, parameters.bits[0]);
    for (let ch = 0; ch < output.length; ch++) {
      const src = input[ch] || input[0];
      if (!src) continue;
      for (let i = 0; i < output[ch].length; i++) output[ch][i] = step * Math.round(src[i] / step);
    }
    return true;
  }
}
registerProcessor("sample-crusher", SampleCrusher);
